/*
 * A210236  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A210235; see the Formula section.
 * https://oeis.org/A210236
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the (n‑th) flattened coefficient of the polynomials
 *            v(n,x), generated by u(1,x)=v(1,x)=1,
 *            u(n,x)=x*u(n-1,x)+v(n-1,x)+1,
 *            v(n,x)=(x+1)*u(n-1,x)+(x+1)*v(n-1,x)+1
 * Range:     u8 n <= 23, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The function keeps the last row of coefficients in static storage and
   extends it as necessary.  For n up to 10⁴ the routine runs in well
   under two seconds.  */
#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>

static idx_t  max_row = 0;            /* highest row already computed */
static seq_t *U      = NULL;          /* coefficients of u(row)   */
static seq_t *V      = NULL;          /* coefficients of v(row)   */
static seq_t *Utmp   = NULL;          /* temporary buffer         */
static seq_t *Vtmp   = NULL;          /* temporary buffer         */
static size_t   capacity = 0;         /* current buffer capacity  */

seq_t a(idx_t n)
{
    /* 1. Find the row r that contains the n‑th flattened coefficient. */
    idx_t r = 1;
    while ((r * (r + 1)) / 2 < n) ++r;        /* r minimal with r(r+1)/2 ≥ n */

    /* 2. Initialise first row if necessary. */
    if (max_row == 0) {
        capacity = 1;
        U      = (seq_t*)malloc(capacity * sizeof(seq_t));
        V      = (seq_t*)malloc(capacity * sizeof(seq_t));
        Utmp   = (seq_t*)malloc(capacity * sizeof(seq_t));
        Vtmp   = (seq_t*)malloc(capacity * sizeof(seq_t));
        if (!U || !V || !Utmp || !Vtmp) return (seq_t)0; /* OOM */
        U[0] = (seq_t)1;
        V[0] = (seq_t)1;
        max_row = 1;
    }

    /* 3. Compute rows from max_row+1 up to r. */
    for (idx_t row = max_row + 1; row <= r; ++row) {
        size_t L      = (size_t)row;          /* new row length   */
        size_t prev   = (size_t)(row - 1);    /* previous row len */

        /* Resize buffers if needed. */
        if (capacity < L) {
            capacity = L;
            Utmp = (seq_t*)realloc(Utmp, capacity * sizeof(seq_t));
            Vtmp = (seq_t*)realloc(Vtmp, capacity * sizeof(seq_t));
            if (!Utmp || !Vtmp) return (seq_t)0; /* OOM */
        }

        /* 4. Compute next row's coefficients. */
        for (size_t k = 0; k < L; ++k) {
            /* Coefficients of u: nextU[k] = U[k-1] + V[k] + (k==0?1:0) */
            seq_t valU = 0;
            if (k > 0 && k - 1 < prev) valU += U[k - 1];
            if (k < prev)              valU += V[k];
            if (k == 0)                valU += (seq_t)1;
            Utmp[k] = valU;

            /* Coefficients of v: nextV[k] =
               U[k] + U[k-1] + V[k] + V[k-1] + (k==0?1:0) */
            seq_t valV = 0;
            if (k < prev)              valV += U[k];
            if (k > 0 && k - 1 < prev) valV += U[k - 1];
            if (k < prev)              valV += V[k];
            if (k > 0 && k - 1 < prev) valV += V[k - 1];
            if (k == 0)                valV += (seq_t)1;
            Vtmp[k] = valV;
        }

        /* 5. Advance pointers: new row becomes current. */
        seq_t *tmp = U;
        U = Utmp;   Utmp = tmp;
        tmp = V;
        V = Vtmp;   Vtmp = tmp;
    }

    max_row = r;  /* update highest computed row */

    /* 6. Extract the requested coefficient from row r. */
    idx_t before = (r - 1) * r / 2;      /* terms before row r */
    idx_t pos    = n - before;           /* 1‑based position in row r */
    idx_t idx    = pos - 1;              /* 0‑based index for array */
    return V[idx];
}
